private void reload(List<Set<Integer>> bucketsByLabel,List<Integer> labels,int minLabel){
    int newLabel = 0; // Label for empty buckets
    for (int label : labels) {
        if (label >= minLabel) {
            bucketsByLabel.set(label, new HashSet<>());
        }
        // Clear the vertex from the original bucket
        bucketsByLabel.get(minLabel).remove(label);
        // Update the vertex label
        labels.set(labels.indexOf(label), newLabel);
    }
    // Update the minimum label in the list
    minLabel = 0;
}

