public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int utf8Size = 0;
    byte[] buffer = new byte[4];
    while (len-- > 0) {
        byte b = str.charAt(index++) & 0xFF;
        if (b >= 0 && b <= 0x7F) {
            utf8Size += 1;
        } else if (b >= 0b1100_0000 && b <= 0b1110_1101) {
            utf8Size += 2;
        } else if (b >= 0b1111_0000 && b <= 0b1111_1111) {
            if (b == 0b1111_1111) {
                if (len >= 3) {
                    if ((str.charAt(index) & 0b1100_0000) == 0b1100_0000 && (str.charAt(index + 1) & 0b1110_1101) == 0b1110_1101) {
                        buffer[0] = str.charAt(index++) & 0xFF;
                        buffer[1] = str.charAt(index++) & 0xFF;
                        buffer[2] = str.charAt(index++) & 0xFF;
                        utf8Size += 3;
                        encodeUTF8(new String(buffer), utf8Size, len - 2, buffer);
                    } else {
                        return -1; // Invalid trailing sequence
                    }
                } else {
                    return -1; // Short read of sequence
                }
            } else {
                utf8Size += 3;
            }
        } else {
            return -1; // Character outside UTF-8 range
        }
    }
    return utf8Size;
}

